const ahoraAR = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' }));
const dia = ahoraAR.getDay(); // 0=domingo
const hora = ahoraAR.getHours();
const diaTurno = hora < 6 ? (dia + 6) % 7 : dia; // la madrugada cuenta como el día anterior
const cierraTarde = diaTurno === 5 || diaTurno === 6; // viernes y sábados hasta la 1am
const abierto = diaTurno !== 1 && (hora >= 19 || (hora < 1 && cierraTarde)); // cerrado los lunes

// Una sola respuesta automática por contacto cada 3 horas.
// (staticData solo persiste con el workflow activo, no en ejecuciones manuales)
const memoria = $getWorkflowStaticData('global');
memoria.contactos = memoria.contactos || {};
const ahora = Date.now();
const TRES_HORAS = 3 * 60 * 60 * 1000;
for (const numero of Object.keys(memoria.contactos)) {
  if (ahora - memoria.contactos[numero] > TRES_HORAS) delete memoria.contactos[numero];
}

return $input.all()
  .filter(item => item.json.messages?.length) // ignora eventos de estado (entregado, leído)
  .filter(item => {
    const numero = item.json.messages[0].from;
    if (memoria.contactos[numero]) return false;
    memoria.contactos[numero] = ahora;
    return true;
  })
  .map(item => ({ json: { ...item.json, fueraDeHorario: !abierto } }));
